import { hdImages, type HdImageName } from "@/lib/hd-images";

const srcSet = (name: HdImageName, ext: string) => (hdImages[name].widths as readonly number[]).map((w) => `/images/hd/${name}-${w}.${ext} ${w}w`).join(", ");

/** Shows a photo pre-generated by `npm run images`. Fills its nearest positioned parent. */
export function HdImage({
  name,
  alt = "",
  sizes = "100vw",
  priority = false,
  position,
  className = "",
}: {
  name: HdImageName;
  alt?: string;
  sizes?: string;
  priority?: boolean;
  position?: string;
  className?: string;
}) {
  return (
    <picture>
      <source type="image/avif" srcSet={srcSet(name, "avif")} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet(name, "webp")} sizes={sizes} />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={`/images/hd/${name}.jpg`}
        alt={alt}
        width={hdImages[name].width}
        height={hdImages[name].height}
        loading={priority ? "eager" : "lazy"}
        fetchPriority={priority ? "high" : "auto"}
        decoding={priority ? "sync" : "async"}
        style={{ objectPosition: position, backgroundImage: `url(${hdImages[name].blur})`, backgroundSize: "cover", backgroundPosition: position ?? "center" }}
        className={`absolute inset-0 h-full w-full object-cover ${className}`}
      />
    </picture>
  );
}
